def _optional_float(value):
    return None if value is None or pd.isna(value) else float(value)

def _build_market_context(provider,cfg,resolved):
    mcfg=cfg["market_regime"]; bcfg=mcfg.get("breadth_52w",{}); icfg=mcfg.get("intraday_strength",{}); regimes={}; breadths={}; intradays={}
    for market in ("KOSPI","KOSDAQ"):
        try: index_df=provider.get_market_index(market,resolved)
        except Exception as exc: print(f"[WARN] {market} market regime index load failed: {exc}"); index_df=pd.DataFrame(columns=["open","high","low","close"])
        regimes[market]=classify_market_regime(index_df,market=market,ma_short=int(mcfg.get("ma_short",50)),ma_long=int(mcfg.get("ma_long",150)),slope_lookback=int(mcfg.get("slope_lookback",20)),experimental_slope_threshold_pct=float(mcfg.get("experimental_slope_threshold_pct",0.30)))
        try:
            if not bool(icfg.get("enabled",True)): raise RuntimeError("intraday-strength proxy disabled")
            hist=compute_intraday_strength_history(index_df,strong_clv_threshold=float(icfg.get("strong_clv_threshold",0.70)),weak_clv_threshold=float(icfg.get("weak_clv_threshold",0.30)),short_window=int(icfg.get("short_window",5)),long_window=int(icfg.get("long_window",20)))
            intradays[market]=latest_intraday_snapshot(hist,market=market,short_window=int(icfg.get("short_window",5)),long_window=int(icfg.get("long_window",20)))
        except Exception as exc: print(f"[WARN] {market} intraday-strength proxy failed: {exc}"); intradays[market]=latest_intraday_snapshot(pd.DataFrame(),market=market,short_window=int(icfg.get("short_window",5)),long_window=int(icfg.get("long_window",20)))
        try:
            source,meta=provider.get_market_breadth_source(market,resolved); hist=compute_52w_breadth_history(source,lookback_sessions=int(bcfg.get("lookback_sessions",252)),min_history_sessions=int(bcfg.get("min_history_sessions",252)),short_window=int(bcfg.get("short_window",5)),long_window=int(bcfg.get("long_window",20)))
            breadths[market]=latest_breadth_snapshot(hist,market=market,min_coverage_ratio=float(bcfg.get("min_coverage_ratio",0.60)),snapshot_dates_loaded=int(meta.get("loaded_dates",0)),snapshot_dates_expected=int(meta.get("expected_dates",0)),source_mode=str(meta.get("source_mode","UNKNOWN")),membership_mode=str(meta.get("membership_mode","UNKNOWN")),source_ticker_count=int(meta.get("ticker_count",0)),failed_tickers=int(meta.get("failed_tickers",0)))
        except Exception as exc: print(f"[WARN] {market} 52W breadth analysis failed: {exc}"); breadths[market]=latest_breadth_snapshot(pd.DataFrame(),market=market,min_coverage_ratio=float(bcfg.get("min_coverage_ratio",0.60)))
    return regimes,breadths,intradays

def _build_rs_context(provider,cfg,resolved,universe):
    rcfg=cfg.get("relative_strength",{}); sw=int(rcfg.get("short_window",20)); lw=int(rcfg.get("long_window",60)); minp=float(rcfg.get("experimental_min_percentile",80.0)); snapshots={}; rows=[]
    for ticker,info in universe.iterrows():
        code=str(ticker).zfill(6); market=str(info.get("market","")).upper()
        try:
            if not bool(rcfg.get("enabled",True)): raise RuntimeError("relative-strength analysis disabled")
            snap=compute_relative_strength_snapshot(provider.get_daily(code,resolved),provider.get_market_index(market,resolved),market=market,short_window=sw,long_window=lw,as_of=resolved)
        except Exception as exc: print(f"[WARN] {code} relative-strength analysis failed: {exc}"); snap=compute_relative_strength_snapshot(pd.DataFrame(columns=["close"]),pd.DataFrame(columns=["close"]),market=market,short_window=sw,long_window=lw,as_of=resolved)
        snapshots[code]=snap; rows.append({"ticker":code,"market":market,"rs_20d_pct":snap.rs_20d_pct,"rs_60d_pct":snap.rs_60d_pct})
    ranks={}
    if rows:
        for _,row in add_cross_sectional_rs_percentiles(pd.DataFrame(rows)).iterrows():
            p20=_optional_float(row.get("rs_percentile_20d")); p60=_optional_float(row.get("rs_percentile_60d")); comp=_optional_float(row.get("rs_percentile_composite")); ranks[str(row["ticker"]).zfill(6)]={"rs_percentile_20d":p20,"rs_percentile_60d":p60,"rs_percentile_composite":comp,"rs_experimental_percentile_pass":bool(comp is not None and comp>=minp)}
    return snapshots,ranks

